var getStatistics = async (req, res, next2) => {
  try {
    const months = [
      "Jan",
      "Feb",
      "Mar",
      "Apr",
      "May",
      "Jun",
      "Jul",
      "Aug",
      "Sep",
      "Oct",
      "Nov",
      "Dec"
    ];
    const [users, parents, providers] = await Promise.all([
      user_model_default.aggregate([
        {
          $group: {
            _id: { $month: "$createdAt" },
            count: { $sum: 1 }
          }
        }
      ]),
      parent_model_default.aggregate([
        {
          $group: {
            _id: { $month: "$createdAt" },
            count: { $sum: 1 }
          }
        }
      ]),
      provider_model_default.aggregate([
        {
          $group: {
            _id: { $month: "$createdAt" },
            count: { $sum: 1 }
          }
        }
      ])
    ]);
    const userMap = new Map(
      users.map((item) => [item._id, item.count])
    );
    const parentMap = new Map(
      parents.map((item) => [item._id, item.count])
    );
    const providerMap = new Map(
      providers.map((item) => [item._id, item.count])
    );
    const result = months.map((month, index3) => {
      const monthNumber = index3 + 1;
      return {
        name: month,
        user: userMap.get(monthNumber) || 0,
        parent: parentMap.get(monthNumber) || 0,
        provider: providerMap.get(monthNumber) || 0
      };
    });
    res.status(200).json({
      success: true,
      data: result
    });
  } catch (error2) {
    console.error("Error fetching statistics:", error2);
    return next2(errorHandler2(500, "Error fetching statistics"));
  }
};

// middlewares/authMiddleware.js
var import_jsonwebtoken = __toESM(require_jsonwebtoken(), 1);
var verifyAdminToken = async (req, res, next2) => {
  try {
    let token3 = req.cookies?.token;
    if (!token3 && req.headers.authorization) {
      const authHeader = req.headers.authorization;
      token3 = authHeader.startsWith("Bearer ") ? authHeader.split(" ")[1] : authHeader;
    }
    if (!token3) {
      return res.status(401).json({
        success: false,
        message: "No token provided"
      });
    }
    const decoded = import_jsonwebtoken.default.verify(token3, process.env.JWT_SECRET);
    const user = await user_model_default.findById(decoded.id).populate("role");
    if (!user) {
      return res.status(401).json({
        success: false,
        message: "User not found"
      });
    }
    req.user = {
      id: user._id,
      username: user.username,
      role: user.role.role,
      permissions: user.role.permissions,
      isAdmin: user.role.role === "Admin" || user.role.role === "Super Admin"
    };
    next2();
  } catch (error2) {
    console.error("Verify token error:", error2);
    return res.status(401).json({
      success: false,
      message: "Invalid or expired token"
    });
  }
};

