articleSchema.pre("validate", async function(next2) {
  if (!this.title) return next2();
  const baseSlug = this.title.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  const regex = new RegExp(`^${baseSlug}(-\\d+)?$`);
  const existing = await import_mongoose5.default.models.Article.find({ slug: regex }).select(
    "slug"
  );
  if (existing.length === 0) {
    this.slug = baseSlug;
    return next2();
  }
  const numbers = existing.map((doc) => {
    const match = doc.slug.match(/-(\d+)$/);
    return match ? parseInt(match[1]) : 0;
  }).sort((a, b3) => b3 - a);
  const nextNumber = numbers[0] + 1;
  this.slug = `${baseSlug}-${nextNumber}`;
  next2();
});
