var createCategory = async (req, res, next2) => {
  try {
    const { name: name2, description, icon, color, order } = req.body;
    if (!name2 || !description || order === void 0) {
      return res.status(400).json({
        success: false,
        message: "Name, description and order are required"
      });
    }
    const existingCategory = await category_model_default.findOne({
      name: { $regex: new RegExp(`^${name2}$`, "i") }
    });
    if (existingCategory) {
      return res.status(400).json({
        message: "Category already exists"
      });
    }
    const existingOrder = await category_model_default.findOne({ order });
    if (existingOrder) {
      return res.status(400).json({
        success: false,
        message: "Order already exists"
      });
    }
    const category = new category_model_default({
      name: name2,
      description,
      icon: icon || "\u{1F4DD}",
      color: color || "#65467C",
      order
    });
    await category.save();
    res.status(201).json({
      success: true,
      message: "Category created successfully",
      category
    });
  } catch (error2) {
    console.error("Create category error:", error2);
    next2(error2);
  }
};
var updateCategory = async (req, res, next2) => {
  try {
    const { id } = req.params;
    const { name: name2, description, icon, color, order, isActive } = req.body;
    const category = await category_model_default.findById(id);
    if (!category) {
      return res.status(404).json({
        message: "Category not found"
      });
    }
    if (name2 !== void 0) {
      if (!name2.trim()) {
        return res.status(400).json({
          message: "Name is required"
        });
      }
      if (name2 !== category.name) {
        const existingCategory = await category_model_default.findOne({
          name: { $regex: new RegExp(`^${name2}$`, "i") },
          _id: { $ne: id }
        });
        if (existingCategory) {
          return res.status(400).json({
            message: "Category name already exists"
          });
        }
        await article_model_default.updateMany(
          { category: category.name },
          { category: name2 }
        );
      }
      category.name = name2.trim();
    }
    if (description !== void 0) {
      if (!description.trim()) {
        return res.status(400).json({
          message: "Description is required"
        });
      }
      category.description = description.trim();
    }
    if (icon !== void 0) category.icon = icon;
    if (color !== void 0) category.color = color;
    if (order !== void 0) {
      const orderNumber = Number(order);
      const existingOrder = await category_model_default.findOne({
        order: orderNumber,
        _id: { $ne: id }
      });
      if (existingOrder) {
        return res.status(400).json({
          success: false,
          message: "Order already exists"
        });
      }
      category.order = orderNumber;
    }
    if (isActive !== void 0) {
      category.isActive = isActive;
    }
    await category.save();
    res.status(200).json({
      success: true,
      message: "Category updated successfully",
      category
    });
  } catch (error2) {
    console.error("Update category error:", error2);
    next2(error2);
  }
};
