var createAdmin = async (req, res, next2) => {
  try {
    const { username, email, password, profilePicture, role } = req.body;
    const existingUser = await user_model_default.findOne({ email });
    if (existingUser) {
      return next2(errorHandler2(400, "User already exists"));
    }
    const selectedRole = await role_model_default.findOne({ role });
    const roleName = selectedRole.role.toLowerCase();
    if (roleName === "super admin") {
      const existingSuperAdmin = await user_model_default.findOne({
        role: selectedRole._id
      });
      if (existingSuperAdmin) {
        return next2(
          errorHandler2(403, "Only one Super Admin is allowed")
        );
      }
    }
    const hashedPassword = await import_bcrypt.default.hash(password, 10);
    const adminUser = new user_model_default({
      username,
      email,
      password: hashedPassword,
      role: selectedRole._id,
      profilePicture
    });
    await adminUser.save();
    res.status(201).json({
      success: true,
      message: `${role} created successfully`
    });
  } catch (error2) {
    console.error("Create admin error:", error2);
    return next2(errorHandler2(500, "Internal server error"));
  }
};
var login = async (req, res, next2) => {
  try {
    const { username, password } = req.body;
    if (!username || !password) {
      return next2(errorHandler2(400, "Username and password are required"));
    }
    const user = await user_model_default.findOne({ username }).populate("role");
    if (!user || !user.role) {
      return next2(errorHandler2(401, "Invalid credentials"));
    }
    const isMatch = await import_bcrypt.default.compare(password, user.password);
    if (!isMatch) {
      return next2(errorHandler2(401, "Invalid credentials"));
    }
    const token3 = import_jsonwebtoken2.default.sign(
      {
        id: user._id,
        role: user.role.role,
        permissions: user.role.permissions,
        isSuperAdmin: user.role.isSuperAdmin,
        profilePicture: user.profilePicture
      },
      process.env.JWT_SECRET,
      { expiresIn: "1d" }
    );
    res.cookie("token", token3, {
      httpOnly: true,
      secure: process.env.NODE_ENV === "production",
      sameSite: "none",
      path: "/"
    });
    res.status(200).json({
      success: true,
      user: {
        id: user._id,
        username: user.username,
        role: user.role.role,
        permissions: user.role.permissions,
        isSuperAdmin: user.role.isSuperAdmin,
        profilePicture: user.profilePicture
      }
    });
  } catch (error2) {
    console.error("Login error:", error2);
    return next2(errorHandler2(500, "Login failed"));
  }
};
