// utils/verifyRoles.js
var verifyRoles = (...allowedRoles) => {
  return (req, res, next2) => {
    if (!req.user || !allowedRoles.includes(req.user.role)) {
      return res.status(403).json({
        success: false,
        message: "Access denied"
      });
    }
    next2();
  };
};

