// controller/help.controller.js
var VALID_CATEGORIES = [
  "Account & Access",
  "Payment & Billing",
  "Booking & Scheduling",
  "Technical Support",
  "Report a Bug",
  "General Inquiry"
];
var VALID_PRIORITIES = ["Low", "Medium", "High"];
var createTicket = async (req, res, next2) => {
  try {
    const { email, category, description, priority, title, attachment } = req.body;
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!email || !emailRegex.test(email)) {
      return next2(errorHandler2(400, "A valid email address is required."));
    }
    if (!category || !VALID_CATEGORIES.includes(category)) {
      return next2(errorHandler2(400, "Please select a valid category."));
    }
    if (!description || !description.trim()) {
      return next2(errorHandler2(400, "Please describe your issue."));
    }
    if (priority && !VALID_PRIORITIES.includes(priority)) {
      return next2(errorHandler2(400, "Invalid priority level."));
    }
    const ticket = await help_model_default.create({
      user: req.user?.id,
      email: email.toLowerCase(),
      title: title?.trim() || description.trim().slice(0, 60),
      category,
      description: description.trim(),
      priority: priority || "Medium",
      attachment
    });
    res.status(201).json({ success: true, ticket });
  } catch (error2) {
    next2(error2);
  }
};
var getMyTickets = async (req, res, next2) => {
  try {
    const { search, status } = req.query;
    const query = {
      $or: [{ user: req.user.id }, { email: req.user.email }]
    };
    if (status && status !== "All") {
      query.status = status;
    }
    if (search) {
      const term = search.trim();
      query.$and = [
        {
          $or: [
            { title: { $regex: term, $options: "i" } },
            { ticketId: { $regex: term, $options: "i" } }
          ]
        }
      ];
    }
    const tickets = await help_model_default.find(query).sort({ createdAt: -1 }).lean();
    res.status(200).json({ success: true, tickets });
  } catch (error2) {
    next2(error2);
  }
};
