var updateServiceSpecialization = async (req, res) => {
  try {
    const {
      serviceId,
      specializationId,
      isPrimary,
      displayOrder,
      isActive
    } = req.body;
    const relation = await servicespecialization_model_default.findById(req.params.id);
    if (!relation) {
      return res.status(404).json({
        success: false,
        message: "Relationship not found."
      });
    }
    if (typeof displayOrder !== "undefined") {
      if (displayOrder === null || displayOrder === "" || isNaN(displayOrder)) {
        return res.status(400).json({
          success: false,
          message: "Display Order must be a valid number."
        });
      }
      const existingDisplayOrder = await servicespecialization_model_default.findOne({
        _id: { $ne: req.params.id },
        serviceId: serviceId || relation.serviceId,
        displayOrder: Number(displayOrder)
      });
      if (existingDisplayOrder) {
        return res.status(400).json({
          success: false,
          message: `Display Order ${displayOrder} is already used.`
        });
      }
      relation.displayOrder = Number(displayOrder);
    }
    if (serviceId) {
      const service = await masterData_model_default.findOne({
        _id: serviceId,
        type: "serviceType"
      });
      if (!service) {
        return res.status(404).json({
          success: false,
          message: "Service not found."
        });
      }
      relation.serviceId = serviceId;
    }
    if (specializationId) {
      const specialization = await specialization_model_default.findById(specializationId);
      if (!specialization) {
        return res.status(404).json({
          success: false,
          message: "Specialization not found."
        });
      }
      const duplicate = await servicespecialization_model_default.findOne({
        _id: { $ne: req.params.id },
        serviceId: serviceId || relation.serviceId,
        specializationId
      });
      if (duplicate) {
        return res.status(400).json({
          success: false,
          message: "This mapping already exists."
        });
      }
      relation.specializationId = specializationId;
    }
    if (typeof isPrimary !== "undefined")
      relation.isPrimary = isPrimary;
    if (typeof displayOrder !== "undefined")
      relation.displayOrder = displayOrder;
    if (typeof isActive !== "undefined")
      relation.isActive = isActive;
    await relation.save();
    const updated = await servicespecialization_model_default.findById(relation._id).populate("serviceId", "label code").populate("specializationId", "name code");
    res.json({
      success: true,
      message: "Relationship updated successfully.",
      data: updated
    });
  } catch (error2) {
    res.status(500).json({
      success: false,
      message: error2.message
    });
  }
};
